#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
bool automaticMode = true;
int rawButton = HIGH;
int stableButton = HIGH;
unsigned long buttonChanged = 0;
unsigned long lastMeasurement = 0;
int shownThreshold = -1;

void updateButton(unsigned long now) {
  int reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChanged = now;
  }
  if (rawButton != stableButton && now - buttonChanged >= 40) {
    stableButton = rawButton;
    if (stableButton == LOW) automaticMode = !automaticMode;
  }
}

void measureAndAlarm(int threshold) {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  float distance = duration * 0.0343f / 2.0f;
  if (duration != 0 && distance < threshold) tone(6, 1000);
  else noTone(6);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(6, OUTPUT);
  digitalWrite(8, LOW);
  noTone(6);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  updateButton(now);
  int threshold = automaticMode ? 15 : (int)map(analogRead(A0), 0, 1023, 0, 100);
  if (threshold != shownThreshold) {
    display.showNumberDec(threshold, false);
    shownThreshold = threshold;
  }
  if (now - lastMeasurement >= 80) {
    lastMeasurement = now;
    measureAndAlarm(threshold);
  }
}
